import { Routes } from "@angular/router";
import { AuthGuard } from "./guards/auth.guard";
import { AbertosComponent } from "./pages/abertos/abertos.component";
import { CadastroComponent } from "./pages/auth/cadastro/cadastro.component";
import { ConcluidosComponent } from "./pages/concluidos/concluidos.component";
import { DashboardComponent } from "./pages/dashboard/dashboard.component";
import { LayoutComponent } from "./layout/layout.component";
import { LoginComponent } from "./pages/auth/login/login.component";

export const appRoutes: Routes = [
  { path: "login", component: LoginComponent },
  { path: "cadastro", component: CadastroComponent },
  {
    path: "",
    component: LayoutComponent,
    canActivate: [AuthGuard],
    canActivateChild: [AuthGuard],
    children: [
      { path: "", pathMatch: "full", redirectTo: "dashboard" },
      { path: "abertos", component: AbertosComponent },
      {
        path: "afazer",
        loadComponent: () =>
          import("./pages/afazer/afazer.component").then((m) => m.AfazerComponent)
      },
      {
        path: "calendario",
        loadComponent: () =>
          import("./pages/calendario/calendario.component").then((m) => m.CalendarioComponent)
      },
      {
        path: "anotacoes",
        loadComponent: () =>
          import("./pages/anotacoes/anotacoes.component").then((m) => m.AnotacoesComponent)
      },
      { path: "clientes", redirectTo: "empresas", pathMatch: "full" },
      { path: "concluidos", component: ConcluidosComponent },
      { path: "dashboard", component: DashboardComponent },
      {
        path: "empresas",
        loadComponent: () =>
          import("./pages/empresas/empresas.component").then((m) => m.EmpresasComponent)
      },
      {
        path: "relatorios",
        loadComponent: () =>
          import("./pages/relatorios/relatorios.component").then((m) => m.RelatoriosComponent)
      },
      {
        path: "sistemas",
        loadComponent: () =>
          import("./pages/sistemas/sistemas.component").then((m) => m.SistemasComponent)
      }
    ]
  },
  { path: "**", redirectTo: "" }
];
